159			return s.Route.interfaceText()
160		case stepGateway:
161			return s.Route.gatewayText()
162		}
163		return addrOrDash(s.Hop.Addr)
164	}
165	
166	// rttCell is the round-trip time of a hop that answered; "-" otherwise.
167	func (s pathStep) rttCell() string {
168		if s.Kind != stepHop {
169			return ""
170		}
171		if s.Hop.RTT <= 0 {
172			return "-"
173		}
174		return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
175	}
176	
177	// interfaceText is the interface name, followed by the source address when known.
178	func (r pathRoute) interfaceText() string {
179		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
180			return routeUndetermined
181		}
182		name := r.Interface
183		if name == "" {
184			name = "unnamed"
185		}
186		if !r.Source.IsValid() {
187			return name
188		}
189		return name + " (" + r.Source.String() + ")"
190	}
191	
192	// gatewayText is the gateway address, or says the destination is directly connected.
193	func (r pathRoute) gatewayText() string {
194		switch {
195		case !r.Known:
196			return routeUndetermined
197		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
198			return gatewayDirect
199		}
200		return r.Gateway.String()
201	}
202	
203	// addrOrDash formats an address, or "-" when there is none.
204	func addrOrDash(a netip.Addr) string {
205		if !a.IsValid() {
206			return "-"
207		}
208		return a.String()
209	}
